const randomStr = Array.from({length: 1024}).map(() => String.fromCodePoint(Math.floor(Math.random() * 94) + 33)).join('');

// Implement the session benchmark
const password = "some_not_random_password_that_is_also_long_enough";
const apps = (
  [
